"""Complete built-in BBB action registry (no runtime schema file required)."""
from __future__ import annotations

import json
import re
from dataclasses import dataclass
from functools import lru_cache
from typing import Any

from ..core.exceptions import MutationNotFound, MutationValidationError


@dataclass(frozen=True, slots=True)
class Argument:
    name: str
    type: str
    required: bool
    is_list: bool

    @property
    def graphql_type(self) -> str:
        value = f"[{self.type}!]" if self.is_list else self.type
        return f"{value}!" if self.required else value


@dataclass(frozen=True, slots=True)
class Mutation:
    name: str
    arguments: tuple[Argument, ...]

    def document(self) -> str:
        declarations = ",".join(f"${argument.name}:{argument.graphql_type}" for argument in self.arguments)
        values = ",".join(f"{argument.name}:${argument.name}" for argument in self.arguments)
        operation = f"SBC_{self.name}"
        return f"mutation {operation}({declarations}){{{self.name}({values})}}" if declarations else f"mutation {operation}{{{self.name}}}"


