@lru_cache(maxsize=1)
def load_registry() -> dict[str, Mutation]:
    """Return every BBB action compiled into this module."""
    try:
        mutations = json.loads(ACTION_DEFINITIONS_JSON)["mutations"]
        return {
            item["name"]: Mutation(item["name"], tuple(
                Argument(arg["name"], arg["type"], bool(arg.get("required")), bool(arg.get("isList")))
                for arg in item.get("arguments", [])
            ))
            for item in mutations
        }
    except (KeyError, TypeError, json.JSONDecodeError) as exc:
        raise RuntimeError("built-in SBC action definitions are invalid") from exc

def snake_case(value: str) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", value).lower()


class Actions:
    """All built-in BBB actions as direct Python methods.

    Use camelCase matching BBB, snake_case, or :meth:`call`::

        client.actions.userSetMuted(userId="abc", muted=True)
        client.actions.user_set_muted(user_id="abc", muted=True)
        client.actions.call("userSetMuted", userId="abc", muted=True)
    """
    def __init__(self, client: Any):
        self._client = client
        self._registry = load_registry()
        self._aliases = {name: name for name in self._registry}
        self._aliases.update({snake_case(name): name for name in self._registry})

    @property
    def names(self) -> tuple[str, ...]: return tuple(self._registry)
    def schema(self, name: str) -> Mutation: return self._get(name)
    def _get(self, name: str) -> Mutation:
        canonical = self._aliases.get(name)
        if not canonical: raise MutationNotFound(f"unknown BBB mutation: {name}")
        return self._registry[canonical]
    def build(self, name: str, **variables: Any) -> tuple[str, dict[str, Any]]:
        mutation = self._get(name)
        expected = {argument.name: argument for argument in mutation.arguments}
        argument_aliases = {snake_case(argument.name): argument.name for argument in mutation.arguments}
        normalized: dict[str, Any] = {}
        for key, value in variables.items():
            canonical = argument_aliases.get(key, key)
            if canonical in normalized:
                raise MutationValidationError(f"{mutation.name}: argument {canonical} was supplied more than once")
            normalized[canonical] = value
        variables = normalized
        unknown = set(variables) - set(expected)
        missing = [argument.name for argument in mutation.arguments if argument.required and argument.name not in variables]
        if unknown: raise MutationValidationError(f"{mutation.name}: unknown argument(s): {', '.join(sorted(unknown))}")
        if missing: raise MutationValidationError(f"{mutation.name}: missing required argument(s): {', '.join(missing)}")
        for argument in mutation.arguments:
            if argument.name in variables and variables[argument.name] is None and argument.required:
                raise MutationValidationError(f"{mutation.name}: {argument.name} cannot be None")
            if argument.name in variables and argument.is_list and variables[argument.name] is not None and not isinstance(variables[argument.name], list):
                raise MutationValidationError(f"{mutation.name}: {argument.name} must be a list")
        return mutation.document(), variables
    def call(self, name: str, /, **variables: Any) -> dict[str, Any]:
        mutation = self._get(name)
        # Every generated BBB action has generic lifecycle handlers and its own
        # specific hooks, e.g. ``action_user_set_muted_completed``.
        self._client.emit("action_started", mutation.name, dict(variables))
        self._client.emit(f"action_{snake_case(mutation.name)}_started", dict(variables))
        try:
            document, normalized = self.build(mutation.name, **variables)
            result = self._client.graphql.mutation(document, normalized)
        except Exception as exc:
            self._client.emit("action_failed", mutation.name, dict(variables), exc)
            self._client.emit(f"action_{snake_case(mutation.name)}_failed", dict(variables), exc)
            raise
        self._client.emit("action_completed", mutation.name, normalized, result)
        self._client.emit(f"action_{snake_case(mutation.name)}_completed", normalized, result)
        return result


def _operation_method(name: str):
    def operation(self: Actions, **variables: Any) -> dict[str, Any]:
        return self.call(name, **variables)
    operation.__name__ = name
    operation.__qualname__ = "Actions." + name
    operation.__doc__ = "Run BBB mutation " + name + "."
    return operation

# All schema operations are installed as real class methods in both BBB
# camelCase and ergonomic snake_case form, visible to dir()/inspect/IDEs.
for _operation_name in load_registry():
    setattr(Actions, _operation_name, _operation_method(_operation_name))
    _snake_name = snake_case(_operation_name)
    if _snake_name != _operation_name:
        setattr(Actions, _snake_name, _operation_method(_operation_name))
del _operation_name, _snake_name
